    def is_prime(x: int) -> bool:
        if x <= 1:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    def fibonacci_until(limit: int):
        fibs = []
        a, b = 0, 1
        while a <= limit:
            fibs.append(a)
            a, b = b, a + b
        return fibs

    fib_primes = []
    limit = 100000  # Arbitrary limit to find Fibonacci primes
    fibs = fibonacci_until(limit)

    for fib in fibs:
        if is_prime(fib):
            fib_primes.append(fib)
            if len(fib_primes) == n:
                return fib_primes[-1]

    return -1  # In case n is too large and we don't find enough Fibonacci primes

